import collections

class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        from collections import defaultdict, deque
        indexes = defaultdict(deque)
        for idx, ch in enumerate(s):
            indexes[int(ch)].append(idx)

        # Ensure each digit in t appears at least once in s
        for v in set(int(ch) for ch in t):
            if v not in indexes:
                return False

        for ch in t:
            cur = int(ch)
            if cur not in indexes:
                return False
            # Verify that no smaller digit appears earlier
            for smaller in range(cur):
                if indexes[smaller] and indexes[smaller][0] < indexes[cur][0]:
                    return False
            # Consume this occurrence
            indexes[cur].popleft()
            if not indexes[cur]:
                del indexes[cur]
        return True

